create table public.exam_questions (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,subject_id uuid not null references public.subjects(id) on delete restrict,question_type text not null check(question_type in('MULTIPLE_CHOICE','ESSAY','TRUE_FALSE')),prompt text not null check(char_length(trim(prompt)) between 5 and 10000),options jsonb,answer_key jsonb,explanation text,difficulty text check(difficulty in('EASY','MEDIUM','HARD')),source text not null default 'MANUAL' check(source in('MANUAL','AI_DRAFT')),review_status text not null default 'APPROVED' check(review_status in('DRAFT','PENDING_REVIEW','APPROVED','REJECTED')),reviewed_by_user_id uuid references public.users(id) on delete restrict,reviewed_at timestamptz,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),check((source='MANUAL') or review_status in('DRAFT','PENDING_REVIEW','APPROVED','REJECTED')));create index exam_questions_tenant_subject_idx on public.exam_questions(tenant_id,subject_id);alter table public.exam_questions enable row level security;revoke all on public.exam_questions from anon,authenticated;create policy exam_questions_select_tenant on public.exam_questions for select to authenticated using(tenant_id=public.current_tenant_id());comment on column public.exam_questions.source is 'AI_DRAFT supports future teacher-reviewed AI question generation; it never auto-publishes.';insert into public.permissions(code,name,description) values('exam_questions.read','Read exam questions','View question bank'),('exam_questions.create','Create exam questions','Create question drafts'),('exam_questions.update','Update exam questions','Review question drafts'),('exam_questions.delete','Delete exam questions','Delete questions') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'exam_questions.%' on conflict do nothing;
